/bin/zsh -lc "python3 -B - <<'PY'
from signalnest import UnknownRoute, resolve_route

assert resolve_route(\"email\") == \"standard\"
assert resolve_route(\"SMS\") == \"mobile\"
assert resolve_route(\"  PaGeR  \") == \"urgent\"

try:
    resolve_route(None)
except TypeError:
    pass
else:
    raise AssertionError(\"invalid type accepted\")

try:
    resolve_route(\"carrier-pigeon\")
except UnknownRoute:
    pass
else:
    raise AssertionError(\"unknown route accepted\")
PY"

